def get_location():
    """Fetches the approximate location using the public IP address."""
    try:
        response = requests.get('https://ipinfo.io/json', timeout=10).json()
        city = response.get('city', 'Unknown')
        region = response.get('region', 'Unknown')
        country = response.get('country', 'IN')
        lat, lon = response.get('loc', '0,0').split(',')

        location_str = f"{city}, {region}, {country}"
        map_link = f"https://www.google.com/maps/search/?api=1&query={lat},{lon}"
        return location_str, map_link
    except requests.RequestException as e:
        print(f"Error: Could not fetch location. Check internet connection. {e}")
        return "Location unavailable", None

def send_whatsapp_alert(phone_num, img_path, detected_label):
    """
    Sends a security alert with an image and location via WhatsApp.
    Uses a more reliable method with better error handling.
    """
    print("Preparing WhatsApp alert...")
    try:
        location_str, map_link = get_location()
        current_time_str = time.strftime("%Y-%m-%d %H:%M:%S")

        caption = (
            f"🚨 *CRITICAL ALERT - POTENTIAL SELF-HARM DETECTED* 🚨\n\n"
            f"*Sharp Object Detected:* {detected_label.capitalize()}\n"
            f"*Time:* {current_time_str}\n"
            f"*Location:* {location_str}\n\n"
            f"⚠️ *IMMEDIATE ATTENTION REQUIRED* ⚠️\n"
            f"Please check on the person immediately!"
        )

        if map_link:
            caption += f"\n\n*View on map:* {map_link}"

        # RELIABLE MESSAGE SENDING: Use pywhatkit with immediate timing
        try:
            print("🚀 RELIABLE: Sending alert with immediate timing...")
            
            # Step 1: Copy image to clipboard
            import subprocess
            subprocess.run(['powershell', '-command', f'Set-Clipboard -Path "{os.path.abspath(img_path)}"'], 
                          capture_output=True, timeout=2)
            print("📋 Image copied to clipboard")
            
            # Step 2: Send text message using pywhatkit with current time
            import datetime
            now = datetime.datetime.now()
            # Send message for current minute (immediate)
            pywhatkit.sendwhatmsg(phone_num, caption, now.hour, now.minute, wait_time=5, tab_close=False)
            print("📝 Text message sent!")
            
            # Step 3: Wait 2 seconds, then send image
            time.sleep(2)
            print("📸 Sending image...")
            pyautogui.hotkey('ctrl', 'v')  # Paste image
            time.sleep(1)
            pyautogui.press('enter')  # Send image
            print("✅ Image sent!")
            
        except Exception as e:
            print(f"❌ pywhatkit method failed: {e}")
            print("🔄 Using manual WhatsApp method...")
            
            # Manual method: Open WhatsApp Web and type manually
            import webbrowser
            webbrowser.open("https://web.whatsapp.com")
            time.sleep(5)  # Wait for WhatsApp to load
            
            # Type the phone number and message manually
            pyautogui.typewrite(phone_num.replace('+', ''))
            time.sleep(1)
            pyautogui.press('enter')
            time.sleep(2)
            pyautogui.typewrite(caption)
            time.sleep(1)
            pyautogui.press('enter')
            print("📝 Manual text message sent")
            
            # Send image
            time.sleep(2)
            pyautogui.hotkey('ctrl', 'v')
            time.sleep(1)
            pyautogui.press('enter')
            print("📸 Manual image sent")
        
        # Quick cleanup
        time.sleep(2)
        pyautogui.hotkey('ctrl', 'w')
        print("✅ WhatsApp tab closed.")

    except Exception as e:
        print(f"Error in send_whatsapp_alert: {e}")
    finally:
        # Clean up the temporary image file
        if os.path.exists(img_path):
            os.remove(img_path)
            print(f"Removed temporary file: {img_path}")


def load_model(weights_path, config_path, names_path):
    """Loads the YOLOv3 model and class names from disk."""
    print("Loading YOLOv3 model...")
    try:
        net = cv2.dnn.readNet(weights_path, config_path)
        with open(names_path, "r") as f:
            classes = [line.strip() for line in f.readlines()]
        
        layer_names = net.getLayerNames()
        # Handle different OpenCV versions for getUnconnectedOutLayers()
        try:
            output_layers_indices = net.getUnconnectedOutLayers().flatten()
        except AttributeError:
            output_layers_indices = net.getUnconnectedOutLayers()

        output_layers = [layer_names[i - 1] for i in output_layers_indices]
        print("YOLO model loaded successfully.")
        return net, classes, output_layers
    except FileNotFoundError as e:
        print(f"Fatal Error: Model file not found: {e}. Please download and place it in the script directory.")
        exit()

def initialize_camera(index=0):
    """Initializes and returns the webcam capture object."""
    print("Starting webcam...")
    cap = cv2.VideoCapture(index)
    if not cap.isOpened():
        print("Fatal Error: Could not open webcam. Please check camera connection.")
        exit()
    print("Webcam started successfully.")
    return cap

def process_frame(frame, net, output_layers, classes):
    """Processes a single frame for object detection with optimized speed."""
    height, width, _ = frame.shape
    
    # MAXIMUM SPEED: Use smallest input size for fastest processing
    blob = cv2.dnn.blobFromImage(frame, 0.00392, (224, 224), (0, 0, 0), True, crop=False)
    net.setInput(blob)
    outs = net.forward(output_layers)

    # --- Post-processing detections ---
    class_ids, confidences, boxes = [], [], []
    for out in outs:
        for detection in out:
            scores = detection[5:]
            class_id = np.argmax(scores)
            confidence = scores[class_id]
            if confidence > CONFIG["CONFIDENCE_THRESHOLD"]:
                center_x = int(detection[0] * width)
                center_y = int(detection[1] * height)
                w = int(detection[2] * width)
                h = int(detection[3] * height)
                x = int(center_x - w / 2)
                y = int(center_y - h / 2)
                
                boxes.append([x, y, w, h])
                confidences.append(float(confidence))
                class_ids.append(class_id)
                
    # --- Apply Non-Maximum Suppression ---
    indexes = cv2.dnn.NMSBoxes(boxes, confidences, CONFIG["CONFIDENCE_THRESHOLD"], CONFIG["NMS_THRESHOLD"])
    
    # --- Draw boxes and check for target objects with strict validation ---
    detected_target_in_frame = False
    detected_object = None
    highest_confidence = 0
    
    if len(indexes) > 0:
        for i in indexes.flatten():
            label = str(classes[class_ids[i]])
            confidence = confidences[i]
            
            # Only consider high-confidence detections
            if confidence > CONFIG["CONFIDENCE_THRESHOLD"]:
                color = (0, 0, 255) if label in CONFIG["TARGET_OBJECTS"] else (0, 255, 0)
                
                # Additional validation for target objects
                if label in CONFIG["TARGET_OBJECTS"] and confidence > highest_confidence:
                    # Extra validation: ensure the detection is significant enough
                    x, y, w, h = boxes[i]
                    # Check if bounding box is reasonably sized (not too small)
                    if w > 20 and h > 20:  # Minimum size threshold
                        detected_target_in_frame = True
                        detected_object = label
                        highest_confidence = confidence
                        print(f"VALIDATED: {label} detected with confidence {confidence:.2f}")
                
                x, y, w, h = boxes[i]
                cv2.rectangle(frame, (x, y), (x + w, y + h), color, 2)
                cv2.putText(frame, f"{label.upper()} {confidence:.2f}", (x, y - 10), cv2.FONT_HERSHEY_SIMPLEX, 0.6, color, 2)
            
    return frame, detected_target_in_frame, detected_object


# ==============================================================================
# --- MAIN EXECUTION ---
# ==============================================================================
def main():
    """Main function to run the security camera loop."""
    net, classes, output_layers = load_model(CONFIG["YOLO_WEIGHTS"], CONFIG["YOLO_CONFIG"], CONFIG["COCO_NAMES"])
    cap = initialize_camera()
    last_send_time = 0

    try:
        while True:
            ret, frame = cap.read()
            if not ret:
                print("Warning: Could not read frame from camera. Exiting loop.")
                break

            # FAST DETECTION: Process every frame with optimized settings
            processed_frame, target_detected, detected_object = process_frame(frame, net, output_layers, classes)
            
            # --- Alerting Logic with Debug Info ---
            current_time = time.time()
            cooldown_passed = (current_time - last_send_time) > CONFIG["SEND_COOLDOWN"]

            # Debug: Show detection status
            if target_detected:
                print(f"🔍 DEBUG: Target detected: {detected_object}")
                print(f"🔍 DEBUG: Cooldown passed: {cooldown_passed}")
                print(f"🔍 DEBUG: Time since last alert: {current_time - last_send_time:.1f}s")

            if target_detected and cooldown_passed:
                print(f"🚨 CRITICAL: {detected_object.capitalize()} detected! Potential self-harm situation!")
                
                # Save a snapshot for sending
                timestamp = time.strftime("%Y%m%d_%H%M%S")
                snapshot_path = f"critical_alert_{timestamp}.jpg"
                cv2.imwrite(snapshot_path, processed_frame)
                print(f"📸 Critical snapshot saved: {snapshot_path}")

                # Send alert in a separate step
                send_whatsapp_alert(CONFIG["PHONE_NUMBER"], snapshot_path, detected_object)
                
                last_send_time = current_time # Reset cooldown timer
            elif target_detected and not cooldown_passed:
                print(f"⏰ Cooldown active: {CONFIG['SEND_COOLDOWN'] - (current_time - last_send_time):.1f}s remaining")

            cv2.imshow("Security Feed", processed_frame)

            # --- Quit Condition ---
            if cv2.waitKey(1) & 0xFF == ord('q'):
                print("Exit key 'q' pressed. Shutting down...")
                break
    finally:
        print("Releasing resources...")
        cap.release()
        cv2.destroyAllWindows()
        print("Script closed successfully.")

if __name__ == "__main__":
    # Check for placeholder phone number
    if "XXXXXXXXXX" in CONFIG["PHONE_NUMBER"]:
        print("CRITICAL: Please set your phone number in the CONFIG section before running!")
    else:
        main()